import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { useNavigate, useSearchParams } from 'react-router-dom';
import styles from "./Messanger.module.css";

const Messanger = () => {
    const navigate = useNavigate();
    const [searchParams] = useSearchParams();
    
    // --- Состояния ---
    const [inbox, setInbox] = useState([]); // Список диалогов слева
    const [messages, setMessages] = useState([]); // Сообщения в активном чате
    const [activeChat, setActiveChat] = useState(null); // Выбранный пользователь (объект partner)
    const [messageText, setMessageText] = useState(''); // Текст ввода
    const [currentUserId, setCurrentUserId] = useState(null); // ID текущего юзера
    const [loadingMessages, setLoadingMessages] = useState(false);
    
    // Реф для авто-скролла вниз
    const messagesEndRef = useRef(null);

    // 1. При загрузке получаем ID текущего юзера и список диалогов
    useEffect(() => {
        const initData = async () => {
            const token = localStorage.getItem('access');
            try {
                // Кто я?
                const meResp = await axios.get('http://127.0.0.1:8000/auth/users/me/', {
                    headers: { 'Authorization': `Bearer ${token}` }
                });
                setCurrentUserId(meResp.data.id);

                // Загружаем Inbox
                fetchInbox();
            } catch (err) {
                console.error("Ошибка инициализации:", err);
            }
        };
        initData();
    }, []);

    // 2. Функция загрузки списка диалогов
    const fetchInbox = async () => {
        try {
            const resp = await axios.get('http://127.0.0.1:8000/api/messages/inbox/', {
                headers: { 'Authorization': `Bearer ${localStorage.getItem('access')}` }
            });
            setInbox(resp.data);
        } catch (err) {
            console.error("Ошибка загрузки inbox:", err);
        }
    };

    // 3. Загрузка сообщений при выборе чата
    useEffect(() => {
        if (!activeChat) return;

        const fetchMessages = async () => {
            setLoadingMessages(true);
            try {
                const resp = await axios.get(`http://127.0.0.1:8000/api/messages/conversation/?with=${activeChat.id}`, {
                    headers: { 'Authorization': `Bearer ${localStorage.getItem('access')}` }
                });
                setMessages(resp.data);
                scrollToBottom();
            } catch (err) {
                console.error(err);
            } finally {
                setLoadingMessages(false);
            }
        };

        fetchMessages();
        
        // Опционально: Поллинг (обновление раз в 5 сек)
        const interval = setInterval(fetchMessages, 5000);
        return () => clearInterval(interval);

    }, [activeChat]);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    // 4. Отправка сообщения
    const handleSendMessage = async () => {
        if (!messageText.trim() || !activeChat) return;

        try {
            const resp = await axios.post('http://127.0.0.1:8000/api/messages/', {
                receiver_id: activeChat.id, // Важно: используем ID из активного чата
                text: messageText
            }, {
                headers: { 'Authorization': `Bearer ${localStorage.getItem('access')}` }
            });

            // Добавляем сообщение в список локально (оптимистичный UI)
            setMessages(prev => [...prev, resp.data]);
            setMessageText('');
            scrollToBottom();
            fetchInbox(); // Обновляем левую панель (последнее сообщение)
        } catch (err) {
            console.error("Ошибка отправки:", err);
            alert("Не удалось отправить сообщение ❌");
        }
    };

    // Форматирование времени
    const formatTime = (dateString) => {
        const date = new Date(dateString);
        return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    };


    return ( 
        <div className={styles.msngr_out_container}>
            <div className={styles.msngr_container}>
                
                {/* === ЛЕВАЯ ПАНЕЛЬ (Список чатов) === */}
                <div className={styles.msngr_leftSide}>
                    <div className={styles.msngr_headLeft}>
                        <div className={styles.msngr_logo} onClick={() => navigate('/')}>
                            <img className={styles.msngr_logoImg} src="images/logo.svg" alt="logo"/>
                        </div>
                        <div className={styles.msngr_search}>
                            <img className={styles.msngr_searchImg} src="images/searchZh.svg" alt="search"/>
                        </div>
                    </div>

                    <div className={styles.msngr_chats}>
                        {inbox.length > 0 ? inbox.map((chat, index) => (
                            <div 
                                key={index} 
                                className={`${styles.msngr_chat} ${activeChat?.id === chat.partner.id ? styles.active_chat : ''}`}
                                onClick={() => setActiveChat(chat.partner)}
                            >
                                <div className={styles.msngr_ProfileIconForm}>
                                    <img 
                                        className={styles.msngr_ProfileIcon} 
                                        src={chat.partner.avatar || "images/profile.svg"} 
                                        alt="profile"
                                        onError={(e) => {e.target.src="images/profile.svg"}}
                                    />
                                </div>
                                <div className={styles.msngr_NickBlock}>
                                    <div className={styles.msngr_NickName}>{chat.partner.nickname}</div>
                                    <div className={styles.msngr_HT}>
                                        <div className={styles.msngr_UserName}>
                                            {chat.last_message.am_i_sender ? 'Вы: ' : ''}
                                            {chat.last_message.text.slice(0, 15)}...
                                        </div>
                                        <div className={styles.msngr_Dot}>∙</div>
                                        <div className={styles.msngr_Time}>{formatTime(chat.last_message.created_at)}</div>
                                    </div>
                                </div>
                            </div>
                        )) : (
                            <div style={{padding: '20px', textAlign: 'center', color: '#888'}}>
                                Нет активных чатов 📭
                            </div>
                        )}
                    </div>
                </div>
                
                {/* Разделитель */}
                <div className={styles.msngr_centerSide}></div>


                {/* === ПРАВАЯ ПАНЕЛЬ (Диалог) === */}
                <div className={styles.msngr_rightSide}>
                    {activeChat ? (
                        <>
                            {/* Шапка диалога */}
                            <div className={styles.msngr_headRight}>
                                <div className={styles.msngr_ProfileIconForm}>
                                    <img 
                                        className={styles.msngr_ProfileIcon} 
                                        src={activeChat.avatar || "images/profile.svg"} 
                                        alt="profile"
                                        onError={(e) => {e.target.src="images/profile.svg"}}
                                    />
                                </div>
                                <div className={styles.msngr_NickBlock}>
                                    <div className={styles.msngr_NickName}>{activeChat.nickname}</div>
                                    <div className={styles.msngr_HT}>
                                        <div className={styles.msngr_UserName}>@{activeChat.handle}</div>
                                        <div className={styles.msngr_Dot}>∙</div>
                                        <div className={styles.msngr_Time}>{activeChat.status || 'Online'}</div>
                                    </div>
                                </div>
                            </div>

                            {/* Область сообщений */}
                            <div className={styles.msngr_BottomRight}>
                                <div className={styles.msngr_Messages}> 
                                    {messages.map((msg) => {
                                        // Определяем, мое ли это сообщение
                                        // msg.sender может быть объектом или ID, зависит от сериализатора. 
                                        // Обычно в MessageSerializer sender - это объект UserShortSerializer.
                                        const isMine = (msg.sender.id === currentUserId) || (msg.sender === currentUserId);
                                        
                                        return (
                                            <div key={msg.id} className={styles.msngr_ToMessage}>
                                                <div className={isMine ? styles.msngr_MyMessage : styles.msngr_OtherMessage}>
                                                    {msg.text}
                                                    <span className={styles.msgTime}>{formatTime(msg.created_at)}</span>
                                                </div>
                                            </div>
                                        );
                                    })}
                                    <div ref={messagesEndRef} />
                                </div>
                            </div>


                            {/* Инпут отправки */}
                            <div className={styles.msngr_Sender}>
                                <input 
                                    className={styles.msngr_Input} 
                                    placeholder="Напишите сообщение..."
                                    value={messageText}
                                    onChange={(e) => setMessageText(e.target.value)}
                                    onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
                                />
                                <div className={styles.msngr_SendButtonForm}>
                                    <button 
                                        className={styles.msngr_ButtonSend}
                                        onClick={handleSendMessage}
                                    >
                                        Отправить
                                    </button>
                                </div>
                            </div>
                        </>
                    ) : (
                        <div className={styles.emptyState}>
                            Выберите чат, чтобы начать общение 💬
                        </div>
                    )}
                </div>
                
            </div>
        </div>
    );
}

export default Messanger;
